<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {storeToday} from '../time'
import {usePayrollPage} from '../payrollPage'
import {annualIssue,annualOpeningValid,newWageEvidence} from '../annualWages'
import type {AnnualWagePage,OpeningMonth,AnnualWageWrite,AnnualReconciliation,AnnualWageEvent} from '../annualWages'
import WageEventFields from './WageEventFields.vue'
import WageEventReview from './WageEventReview.vue'
const props=defineProps<{companyId:string;employeeId:string;year:number;sourceVersion?:string|number}>(),emit=defineEmits<{changed:[]}>(),{api,current,store,home,english,message,issue,format}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
const page=ref<AnnualWagePage|null>(null),opened=ref(false),loading=ref(false),busy=ref(false),failure=ref(''),notice=ref(''),editing=ref(false),months=ref<OpeningMonth[]>([]),reason=ref(''),settlement=ref(''),record=ref<AnnualReconciliation|null>(null)
let savedMonths=new WeakSet<OpeningMonth>(),savedEvents=new WeakSet<AnnualWageEvent>()
const reconciliations=computed(()=>{const rows=page.value?.reconciliations||[];return record.value&&!rows.some(r=>r.id===record.value!.id)?[record.value,...rows]:rows})
const actualReviewReady=computed(()=>page.value?.assessment.status==='ready'&&page.value.context.months.length===12&&page.value.context.months.every(m=>['actual','known-zero'].includes(m.state)))
let revision=0,pendingWrite:AnnualWageWrite|null=null,pendingReconcile:{commandId:string;expectedFingerprint:string;settlementMonth:string}|null=null
const path=()=>`/statutory-year-contexts/${encodeURIComponent(props.companyId)}/${encodeURIComponent(props.employeeId)}/${props.year}`
const money=(v:string|null|undefined)=>v??x('未知','Unknown'),errorText=(e:unknown)=>{const code=(e as {code?:string})?.code;return code&&annualIssue(code,english())!==code?annualIssue(code,english()):message(e)}
function clear(){emit('changed');revision++;page.value=null;editing.value=false;months.value=[];reason.value='';record.value=null;failure.value='';notice.value='';pendingWrite=null;pendingReconcile=null;loading.value=false}
watch(()=>[props.companyId,props.employeeId,props.year,props.sourceVersion,store.value],()=>{clear();if(opened.value)void refresh()})
async function refresh(){if(loading.value||busy.value||!props.companyId||!props.employeeId||!Number.isInteger(props.year))return;emit('changed');opened.value=true;const rev=++revision,target=path(),capturedStore=store.value;page.value=null;record.value=null;editing.value=false;loading.value=true;failure.value='';try{const v=await api().get<AnnualWagePage>(target);if(rev!==revision||!current()||capturedStore!==store.value||target!==path())return;if(v.context.companyId!==props.companyId||v.context.employeeId!==props.employeeId||v.context.year!==props.year)throw new Error('Annual context mismatch');page.value=v;pendingWrite=null;pendingReconcile=null;emit('changed')}catch(e){if(rev===revision&&current()){emit('changed');failure.value=errorText(e)}}finally{if(rev===revision)loading.value=false}}
function edit(){if(!page.value?.context.writable||!home.value?.headOffice)return;months.value=JSON.parse(JSON.stringify(page.value.context.openingMonths));savedMonths=new WeakSet(months.value);savedEvents=new WeakSet(months.value.flatMap(m=>m.events));reason.value='';editing.value=true;pendingWrite=null}
function removeMonth(index:number){const month=months.value[index];if(month&&!savedMonths.has(month))months.value.splice(index,1)}
function removeEvent(month:OpeningMonth,index:number){const event=month.events[index];if(event&&!savedEvents.has(event))month.events.splice(index,1)}
function addMonth(){months.value.push({month:'',state:'actual',rawOW:'',cpf:{citizenship:'citizen',birthDate:null,prDate:null,prMode:'GG',electionReference:''},policyId:null,policyVersion:null,recognisedEmployeeCpf:null,recognisedEmployerCpf:null,evidenceReference:'',events:[]})}
async function save(){if(busy.value||!editing.value||!page.value?.context.writable||!home.value?.headOffice)return;failure.value='';if(!reason.value.trim()||months.value.some(m=>!annualOpeningValid(m)||!m.month.startsWith(props.year+'-'))||new Set(months.value.map(m=>m.month)).size!==months.value.length){failure.value=x('请核对外部历史月份、明确零值凭证、当期身份及政策版本。','Review external months, explicit zero evidence, CPF identity and policy revision.');return}const body={expectedVersion:page.value.context.version,months:JSON.parse(JSON.stringify(months.value)).map((m:OpeningMonth)=>({...m,recognisedEmployeeCpf:m.recognisedEmployeeCpf||null,recognisedEmployerCpf:m.recognisedEmployerCpf||null})),reason:reason.value.trim()},key=JSON.stringify(body);if(!pendingWrite||JSON.stringify({expectedVersion:pendingWrite.expectedVersion,months:pendingWrite.months,reason:pendingWrite.reason})!==key)pendingWrite={commandId:crypto.randomUUID(),...body};const rev=revision,target=path(),captured=store.value;emit('changed');busy.value=true;try{const value=await api().put<AnnualWagePage>(target,pendingWrite);if(rev!==revision||!current()||store.value!==captured)return;page.value=value;editing.value=false;pendingWrite=null;notice.value=x('外部历史新修订已保存；内部批准／冻结资料保持原样，请重新计算未确认工资。','External revision saved. Approved and frozen internal sources are retained; recalculate unconfirmed payroll.');emit('changed')}catch(e){if(rev===revision&&current()){emit('changed');failure.value=errorText(e)}}finally{busy.value=false}}
async function reconcile(){if(busy.value||!page.value?.context.writable||!home.value?.headOffice||!actualReviewReady.value||!settlement.value)return;const body={expectedFingerprint:page.value.context.fingerprint,settlementMonth:settlement.value};if(!pendingReconcile||pendingReconcile.expectedFingerprint!==body.expectedFingerprint||pendingReconcile.settlementMonth!==body.settlementMonth)pendingReconcile={commandId:crypto.randomUUID(),...body};const rev=revision,target=path(),captured=store.value;busy.value=true;failure.value='';try{const value=await api().post<AnnualReconciliation>(target+'/reconciliations',pendingReconcile);if(rev!==revision||!current()||captured!==store.value)return;record.value=value;pendingReconcile=null;notice.value=x('责任复核已记录；没有付款、自动抵扣或实际缴纳登记。','Liability review recorded. No payment, automatic offset or remittance has been recorded.')}catch(e){if(rev===revision&&current()){emit('changed');failure.value=errorText(e)}}finally{busy.value=false}}
</script>
<template><section class="wf-section wf-annual"><header class="wf-toolbar"><h3>{{x('年度OW／AW来源与复核','Annual OW / AW sources and review')}} · {{year}}</h3><button type="button" :disabled="loading||busy||!employeeId||!companyId" @click="refresh">{{x('加载／刷新年度资料','Load / refresh annual context')}}</button></header><p v-if="loading" role="status">{{x('正在读取年度来源…','Loading annual sources…')}}</p><p v-if="failure" class="wf-issue" role="alert">{{failure}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="page"><p class="wf-hint">{{x('预测仅取当前有效批准的固定工资；工时未知、政策缺失与历史不足仍为未知。年度额度不等于本月奖金或已缴CPF。','Forecasts use current approved fixed pay. Variable hours, missing policies and missing history remain unknown. Annual capacity is separate from monthly bonus and realised CPF.')}}</p><p>{{x('修订','Revision')}} {{page.context.version}} · {{x('责任状态','Liability state')}} {{page.assessment.status==='ready'?x('资料完整','Complete'):page.assessment.status==='not_applicable'?x('外籍CPF不适用；SDL仍适用','Foreign CPF not applicable; SDL still applies'):x('来源不完整','Incomplete sources')}}</p><p v-for="code in [...page.context.issues,...page.assessment.issues]" :key="code" class="wf-issue">{{annualIssue(code,english())===code?issue(code):annualIssue(code,english())}}</p><dl class="wf-details"><dt>{{x('年度OW','Annual OW')}}</dt><dd>{{money(page.assessment.annualOW)}}</dd><dt>{{x('AW额度／已占用／剩余','AW ceiling / used / remaining')}}</dt><dd>{{money(page.assessment.awCeiling)}} / {{money(page.assessment.usedAW)}} / {{money(page.assessment.remainingAW)}}</dd><dt>{{x('员工／雇主／合计责任差额','Employee / employer / total liability delta')}}</dt><dd>{{money(page.assessment.employeeDelta)}} / {{money(page.assessment.employerDelta)}} / {{money(page.assessment.totalDelta)}}</dd><dt>{{x('需要复核','Review required')}}</dt><dd>{{page.assessment.reviewRequired?x('是','Yes'):page.assessment.status==='incomplete'?x('未知，资料不足','Unknown; incomplete'):x('否','No')}}</dd></dl><div class="wf-table-wrap"><table><thead><tr><th>{{x('月份／状态','Month / state')}}</th><th>OW / CPF OW</th><th>{{x('来源／政策版本','Source / policy revision')}}</th><th>{{x('工资事件与问题','Wage events / issues')}}</th></tr></thead><tbody><tr v-for="m in page.context.months" :key="m.month" :class="{'wf-issue':m.state==='unknown'}"><td>{{m.month}} · {{m.state==='actual'?x('实际','Actual'):m.state==='forecast'?x('批准预测','Approved forecast'):m.state==='known-zero'?x('有依据零值','Evidenced zero'):x('未知','Unknown')}}</td><td>{{money(m.rawOW)}} / {{money(m.cpfOW)}}</td><td>{{m.source}}<br>{{m.policy?.name||'—'}} / {{m.policy?.version??'—'}}</td><td><p v-for="e in m.events" :key="e.evidence.eventId">{{e.evidence.businessType}} · {{e.evidence.classification}} · {{e.amount}} · {{e.evidence.contributionMonth}}</p>{{m.issues.map(issue).join(' · ')}}</td></tr></tbody></table></div><details v-if="page.assessment.allocations.length"><summary>{{x('事件AW额度分配','Event AW allocations')}}</summary><p v-for="a in page.assessment.allocations" :key="a.eventId">{{a.month}} · {{a.eventId}} · {{money(a.amount)}} / {{money(a.eligibleAW)}} / {{money(a.remaining)}} · {{a.source}}</p></details><details v-if="page.assessment.months.length"><summary>{{x('逐原月CPF责任','CPF liability by original month')}}</summary><p v-for="m in page.assessment.months" :key="m.month">{{m.month}} · OW/AW {{money(m.rawOW)}} / {{money(m.rawAW)}} · CPF OW/AW {{money(m.cpfOW)}} / {{money(m.cpfAW)}} · {{x('员工／雇主目标责任','Employee / employer target')}} {{money(m.targetEmployeeCpf)}} / {{money(m.targetEmployerCpf)}} · {{m.rateCode??'—'}} · {{m.issues.map(issue).join(' · ')}}</p></details><small>{{page.context.fingerprint}}</small><details v-if="reconciliations.length" class="wf-section"><summary>{{x('已记录责任复核（历史固定快照）','Recorded liability reviews (historical fixed snapshots)')}}</summary><p class="wf-hint">{{x('以下是历史固定快照，与当前年度评估分开；不表示工资已付款或CPF已缴纳，也不执行自动抵扣。','Historical fixed snapshots are separate from the current assessment. They do not certify salary payment or CPF remittance, and do not apply automatic offsets.')}}</p><article v-for="entry in reconciliations" :key="entry.id"><h4>{{x('所属年／结算期','Year / settlement period')}} {{entry.year}} / {{entry.settlementMonth}}</h4><p>{{x('记录时间','Recorded at')}}: <time :datetime="entry.recordedAt">{{format(entry.recordedAt,'Asia/Singapore')}}</time></p><p>{{x('员工／雇主／合计责任差额','Employee / employer / total liability delta')}}: {{money(entry.assessment.employeeDelta)}} / {{money(entry.assessment.employerDelta)}} / {{money(entry.assessment.totalDelta)}}</p><p>{{x('待复核／更正跟进','Review / correction follow-up')}}: {{entry.assessment.reviewRequired?x('需要','Required'):entry.assessment.status==='incomplete'?x('未知，资料不足','Unknown; incomplete'):x('无差额待办','No delta follow-up')}}</p><small>{{x('历史快照来源指纹','Historical snapshot source fingerprint')}}: {{entry.assessment.fingerprint}}</small></article></details><p v-if="!page.context.writable" class="wf-hint">{{x('只读；仅总部法定事实管理员可维护具体外部历史，不能覆盖内部批准或冻结资料。','Read only. Head-office statutory administrators may maintain external history; internal approved and frozen facts cannot be overwritten.')}}</p><button v-if="page.context.writable&&home?.headOffice&&!editing" type="button" :disabled="busy" @click="edit">{{x('维护外部历史修订','Maintain external history revision')}}</button><form v-if="editing&&page.context.writable&&home?.headOffice" @submit.prevent="save"><fieldset :disabled="busy"><legend>{{x('完整外部历史修订','Complete external history revision')}}</legend><p class="wf-hint">{{x('只补录具体外部历史，不填写未来预测。已保存月份不能移除；可依据凭证修订OW、原CPF责任及政策／身份事实。既有工资事件的完整经济证据与金额只读；撤销或负调整须走更正链。仅本次未保存新增行可移除。','Record specific prior external facts only, not future forecasts. Saved months cannot be removed; evidence can support revisions to OW, original CPF liabilities and policy/identity facts. Existing event amounts and economic evidence are read only; reversals require the correction chain. Only new unsaved rows can be removed.')}}</p><article v-for="(m,i) in months" :key="i" class="wf-section"><div class="wf-grid"><label>{{x('月份','Month')}}<input v-model="m.month" type="month" :readonly="savedMonths.has(m)" required :min="year+'-01'" :max="year+'-12'"></label><label>{{x('状态（必须明确）','State (explicit)')}}<select v-model="m.state"><option value="actual">{{x('实际','Actual')}}</option><option value="known-zero">{{x('有依据零值','Evidenced zero')}}</option></select></label><label>OW<input v-model="m.rawOW" required inputmode="decimal"></label><label>{{x('政策编号','Policy ID')}}<input v-model="m.policyId" required></label><label>{{x('政策版本','Policy revision')}}<input v-model.number="m.policyVersion" type="number" min="1" required></label><label>{{x('原员工CPF责任（缺失保留空）','Original employee CPF (leave absent unknown)')}}<input v-model="m.recognisedEmployeeCpf" inputmode="decimal"></label><label>{{x('原雇主CPF责任（缺失保留空）','Original employer CPF (leave absent unknown)')}}<input v-model="m.recognisedEmployerCpf" inputmode="decimal"></label></div><div v-if="m.cpf" class="wf-grid"><label>{{x('当期CPF身份','Historical CPF identity')}}<select v-model="m.cpf.citizenship"><option value="citizen">{{x('公民','Citizen')}}</option><option value="spr">{{x('永久居民','Permanent resident')}}</option><option value="foreign">{{x('外籍','Foreign')}}</option></select></label><label>{{x('出生日期','Birth date')}}<input v-model="m.cpf.birthDate" type="date" :required="m.cpf.citizenship!=='foreign'"></label><label v-if="m.cpf.citizenship==='spr'">{{x('PR生效日期','PR effective date')}}<input v-model="m.cpf.prDate" type="date" required></label><label v-if="m.cpf.citizenship==='spr'">{{x('PR缴费模式','PR contribution mode')}}<select v-model="m.cpf.prMode"><option>GG</option><option>FG</option><option>FF</option></select></label><label v-if="m.cpf.citizenship==='spr'">{{x('特殊模式依据','Election evidence')}}<input v-model="m.cpf.electionReference"></label></div><label>{{x('具体外部凭证（零值也必须填写）','Specific external evidence (required for zero too)')}}<textarea v-model="m.evidenceReference" required maxlength="1000"/></label><article v-for="(event,j) in m.events" :key="event.evidence.eventId"><template v-if="savedEvents.has(event)"><p class="wf-hint">{{x('已保存工资事件，只读；更正须保留原事件链。','Saved wage event, read only. Corrections retain the original event chain.')}}</p><WageEventReview :month="m.month" :items="[{label:x('外部历史事项','External historical event'),kind:'wage_event',amount:event.amount,eventEvidence:event.evidence}]"/><p>{{x('外部事项来源','External event source')}}: {{event.source}}</p></template><template v-else><label>{{x('事项金额','Event amount')}}<input v-model="event.amount" required inputmode="decimal"></label><label>{{x('外部事项来源','External event source')}}<input v-model="event.source" required></label><WageEventFields :value="event.evidence"/><button type="button" @click="removeEvent(m,j)">{{x('移除事项','Remove event')}}</button></template></article><button v-if="m.state==='actual'" type="button" @click="m.events.push({evidence:newWageEvidence(m.month),amount:'',source:''})">{{x('添加外部事项','Add external event')}}</button><button v-if="!savedMonths.has(m)" type="button" @click="removeMonth(i)">{{x('移除外部月份','Remove external month')}}</button></article><button type="button" @click="addMonth">{{x('添加历史月份','Add historical month')}}</button><label>{{x('修订理由','Revision reason')}}<textarea v-model="reason" required maxlength="1000"/></label><button type="submit">{{x('保存外部事实新修订','Save external revision')}}</button><button type="button" @click="editing=false">{{x('取消编辑','Cancel edit')}}</button></fieldset></form><form v-if="page.context.writable&&home?.headOffice" @submit.prevent="reconcile"><p class="wf-hint">{{x('年度／离职复核仅记录责任；需实际资料完整，不代表实际已缴纳或已付款。','Year-end / termination review records liability only and requires complete actual facts. It does not record remittance or payment.')}}</p><label>{{x('复核结算月份','Review settlement month')}}<input v-model="settlement" type="month" required :min="year+'-01'" :max="storeToday().slice(0,7)" :disabled="busy"></label><button type="submit" :disabled="busy||!actualReviewReady">{{x('记录责任复核','Record liability review')}}</button><p v-if="record">{{x('复核已记录','Review recorded')}} · {{record.settlementMonth}} · {{record.recordedAt}}</p></form></template><p v-else-if="opened&&!loading&&!failure">{{x('年度资料尚不可用。','Annual context is unavailable.')}}</p></section></template>
<style scoped>.wf-annual{border:1px solid #dbe4ee;border-radius:8px;padding:12px;overflow-wrap:anywhere}.wf-annual fieldset{min-width:0}.wf-annual small{display:block;overflow-wrap:anywhere}.wf-annual th,.wf-annual td{white-space:normal;min-width:8rem}.wf-annual .wf-grid{grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr))}.wf-annual label{display:flex;flex-direction:column;gap:4px}</style>
